# Use color_counts directly 
def apply_transformation_v3(grid):
    rows = len(grid)
    cols = len(grid[0])

    # Find background color (most common)
    counts = {}
    for r in range(rows):
        for c in range(cols):
            color = grid[r][c]
            counts[color] = counts.get(color, 0) + 1

    bg = [c for c, count in counts.items() if count == max(counts.values())][0]

    result = [[bg]*cols for _ in range(rows)]

    # For each non-background color, find its bbox and check fill ratio
    for color in sorted(counts.keys()):
        if color == bg:
            continue

        positions = []
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == color:
                    positions.append((r,c))

        if not positions:
            continue

        min_r = min(p[0] for p in positions)
        max_r = max(p[0] for p in positions)
        min_c = min(p[1] for p in positions)
        max_c = max(p[1] for p in positions)

        bbox_area = (max_r - min_r + 1) * (max_c - min_c + 1)
        actual_count = len(positions)
        fill_ratio = actual_count / bbox_area

        print(f"Color {color}: bbox [{min_r},{max_r}x{min_c},{max_c}], ratio={fill_ratio:.2f}, count={actual_count}")

        if fill_ratio >= 0.5:
            for r in range(min_r, max_r+1):
                for c in range(min_c, max_c+1):
                    result[r][c] = color

    return result

